package com.smritisathi.app.caregiver;
import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;public class PatientDetailActivity extends BaseActivity {String id;TextView stats;@Override public void onCreate(Bundle b){super.onCreate(b);id=getIntent().getStringExtra("patientId");header(getIntent().getStringExtra("patientName")+" — Overview");stats=UI.card(this,"Loading analytics...");root.addView(stats);Button alerts=UI.button(this,"⚠ View Alerts");root.addView(alerts);alerts.setOnClickListener(v->{startActivity(new android.content.Intent(this,CaregiverAlertsActivity.class));});load();}void load(){if(id==null||id.startsWith("demo")){stats.setText("7-day overview\nSessions: 14\nAverage accuracy: 78%\nAverage reaction time: 1.9s\n\n30-day trend available when the backend analytics endpoint is connected.");return;}ApiClient.request("GET","/sessions/patient/"+id+"/stats",Session.token(this),null,(ok,d,e)->{if(ok&&d.has("data")){JsonObject x=d.getAsJsonObject("data");stats.setText("Sessions: "+x.get("totalSessions").getAsInt()+"\nAverage accuracy: "+x.get("avgAccuracy").getAsDouble()+"%\nAverage reaction time: "+x.get("avgReactionTimeMs").getAsDouble()+" ms");}else stats.setText("Analytics unavailable: "+e);});}}
